import os
from urllib.parse import urlencode, urljoin

import requests

AUTH0_DOMAIN = os.getenv("AUTH0_DOMAIN")
AUTH0_CLIENT_ID = os.getenv("AUTH0_CLIENT_ID")
AUTH0_CLIENT_SECRET = os.getenv("AUTH0_CLIENT_SECRET")
AUTH0_REDIRECT_URI = os.getenv("AUTH0_REDIRECT_URI")
AUTH0_AUDIENCE = os.getenv("AUTH0_AUDIENCE")
AUTH0_SCOPE = os.getenv("AUTH0_SCOPE", "openid profile email")


class Auth0OAuthError(Exception):
    pass


def get_authorization_url(state: str, nonce: str | None = None, connection: str | None = None) -> str:
    if not AUTH0_DOMAIN or not AUTH0_CLIENT_ID or not AUTH0_REDIRECT_URI:
        raise Auth0OAuthError("Missing AUTH0_DOMAIN, AUTH0_CLIENT_ID, or AUTH0_REDIRECT_URI")

    params = {
        "response_type": "code",
        "client_id": AUTH0_CLIENT_ID,
        "redirect_uri": AUTH0_REDIRECT_URI,
        "scope": AUTH0_SCOPE,
        "state": state,
    }
    if AUTH0_AUDIENCE:
        params["audience"] = AUTH0_AUDIENCE
    if nonce:
        params["nonce"] = nonce
    if connection:
        params["connection"] = connection

    return f"https://{AUTH0_DOMAIN}/authorize?{urlencode(params)}"


def handle_callback(query_params: dict[str, str]) -> dict:
    if not AUTH0_DOMAIN or not AUTH0_CLIENT_ID or not AUTH0_CLIENT_SECRET or not AUTH0_REDIRECT_URI:
        raise Auth0OAuthError(
            "Missing AUTH0_DOMAIN, AUTH0_CLIENT_ID, AUTH0_CLIENT_SECRET, or AUTH0_REDIRECT_URI"
        )

    error = query_params.get("error")
    if error:
        raise Auth0OAuthError(query_params.get("error_description") or error)

    code = query_params.get("code")
    if not code:
        raise Auth0OAuthError("Missing authorization code")

    token_url = f"https://{AUTH0_DOMAIN}/oauth/token"
    payload = {
        "grant_type": "authorization_code",
        "client_id": AUTH0_CLIENT_ID,
        "client_secret": AUTH0_CLIENT_SECRET,
        "code": code,
        "redirect_uri": AUTH0_REDIRECT_URI,
    }

    resp = requests.post(
        token_url,
        json=payload,
        headers={"Content-Type": "application/json"},
        timeout=30,
    )
    if resp.status_code >= 400:
        raise Auth0OAuthError(f"Token exchange failed: {resp.status_code} {resp.text}")

    token_data = resp.json()
    if "access_token" not in token_data:
        raise Auth0OAuthError(f"Invalid token response: {token_data}")

    return {
        "provider": "auth0",
        "token_endpoint": token_url,
        "tokens": {
            "access_token": token_data.get("access_token"),
            "id_token": token_data.get("id_token"),
            "refresh_token": token_data.get("refresh_token"),
            "token_type": token_data.get("token_type"),
            "expires_in": token_data.get("expires_in"),
            "scope": token_data.get("scope"),
        },
    }


def exchange_authorization_code(code: str) -> dict:
    return handle_callback({"code": code})


def get_userinfo(access_token: str) -> dict:
    if not AUTH0_DOMAIN:
        raise Auth0OAuthError("Missing AUTH0_DOMAIN")

    userinfo_url = f"https://{AUTH0_DOMAIN}/userinfo"
    resp = requests.get(
        userinfo_url,
        headers={"Authorization": f"Bearer {access_token}"},
        timeout=30,
    )
    if resp.status_code >= 400:
        raise Auth0OAuthError(f"Userinfo request failed: {resp.status_code} {resp.text}")
    return resp.json()
